    Art.finalizeTest(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification)
  }

  /** helper function to set the values of all input ports.
   * @param request_arrival payload for data port request_arrival
   */
  def put_concrete_inputs(request_arrival : Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type): Unit = {
    put_request_arrival(request_arrival)
  }


  /** helper function to check Request_Qualification_dispatch_coordination_process_request_qualification's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param arrival_fact method that will be called with the value of the outgoing data
   *        port 'arrival_fact'.
   */
  def check_concrete_output(arrival_fact: Factory_Dispatch_Coordinator.Arrival_Fact.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val arrival_factValue: Factory_Dispatch_Coordinator.Arrival_Fact.Type = get_arrival_fact().get
    if(!arrival_fact(arrival_factValue)) {
      testFailures = testFailures :+ st"'arrival_fact' did not match expected: value of the outgoing data port is ${arrival_factValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_request_arrival(value : Factory_Dispatch_Coordinator.Request_Arrival_Sample.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification.operational_api.request_arrival_Id, Factory_Dispatch_Coordinator.Request_Arrival_Sample_Payload(value))
  }

  // getter for out DataPort
  def get_arrival_fact(): Option[Factory_Dispatch_Coordinator.Arrival_Fact.Type] = {
    val value: Option[Factory_Dispatch_Coordinator.Arrival_Fact.Type] = get_arrival_fact_payload() match {
      case Some(Factory_Dispatch_Coordinator.Arrival_Fact_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port arrival_fact.  Expecting 'Factory_Dispatch_Coordinator.Arrival_Fact_Payload' but received ${v}")
      case _ => None[Factory_Dispatch_Coordinator.Arrival_Fact.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_arrival_fact_payload(): Option[Factory_Dispatch_Coordinator.Arrival_Fact_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_request_qualification.initialization_api.arrival_fact_Id).asInstanceOf[Option[Factory_Dispatch_Coordinator.Arrival_Fact_Payload]]
  }

